// Explicit 15-basis partition; common-frame tree rectangles; fully paid raw word.
// No geometry/group enumeration: 120 roots, 15 bases, 15 nodes per tree.
#define FOUR_BANK_WORD_LIBRARY_ONLY
#include "four_bank_five_stage_word_bounded_20261030.cpp"
#include <limits>
namespace tree_sides {
using Root=std::array<int,8>;
struct Geometry {std::vector<Root> roots;std::array<std::array<unsigned,8>,15> frames{};std::array<unsigned,120> frame{},leaf{},R{},G{};};
unsigned rng=0x2834a71du;
unsigned next(){rng^=rng<<13;rng^=rng>>17;rng^=rng<<5;return rng;}
unsigned pop(unsigned x){return unsigned(__builtin_popcount(x));}
unsigned parity(unsigned x){return unsigned(__builtin_parity(x));}
int dot(const Root& a,const Root& b){int z=0;for(unsigned i=0;i<8;++i)z+=a[i]*b[i];return z;}
bool orth(const Geometry& g,unsigned s,unsigned t){return s!=t&&dot(g.roots[s],g.roots[t])==0;}
unsigned m3(int x){x%=3;return unsigned(x<0?x+3:x);}
std::array<unsigned,16> masks(){std::array<unsigned,16>a{};for(unsigned j=0;j<8;++j)a[8+j]=1u<<j;for(unsigned j=7;j;--j)a[j]=a[2*j]|a[2*j+1];return a;}
const auto mask=masks();
Geometry geometry(){Geometry g;for(unsigned i=0;i<8;++i)for(unsigned j=i+1;j<8;++j)for(int sign:{-1,1}){Root v{};v[i]=2;v[j]=2*sign;g.roots.push_back(v);}for(unsigned b=0;b<128;++b)if(pop(b)%2==0){Root v{};v[0]=1;for(unsigned j=0;j<7;++j)v[1+j]=(b&(1u<<j))?-1:1;g.roots.push_back(v);}check(g.roots.size()==120,"exact 120 root representatives");
 auto id=[&](const Root& v){for(unsigned i=0;i<120;++i)if(g.roots[i]==v)return i;throw std::runtime_error("frame root is absent");};unsigned f=0;
 // Seven XOR one-factorizations of the eight coordinate vertices.
 for(unsigned a=1;a<8;++a){unsigned k=0;for(unsigned x=0;x<8;++x)if(x<(x^a))for(int s:{-1,1}){Root v{};v[x]=2;v[x^a]=2*s;g.frames[f][k++]=id(v);}check(k==8,"coordinate matching gives eight roots");++f;}
 // Eight cosets of the [7,3,4] simplex code inside the even-weight code.
 std::array<unsigned,8> code{};for(unsigned a=0;a<8;++a)for(unsigned x=1;x<8;++x)code[a]|=parity(a&x)<<(x-1);for(unsigned a=1;a<8;++a)check(pop(code[a])==4,"nonzero simplex words have weight four");std::array<bool,128> used{};
 for(unsigned rep=0;rep<128;++rep)if(pop(rep)%2==0&&!used[rep]){check(f<15,"at most fifteen explicit frames");for(unsigned a=0;a<8;++a){const unsigned b=rep^code[a];check(!used[b]&&pop(b)%2==0,"simplex cosets partition even masks");used[b]=true;Root v{};v[0]=1;for(unsigned j=0;j<7;++j)v[j+1]=(b&(1u<<j))?-1:1;g.frames[f][a]=id(v);}++f;}
 check(f==15,"all fifteen bases are constructed, without a search");std::array<unsigned,120> seen{};for(unsigned b=0;b<15;++b)for(unsigned j=0;j<8;++j){const auto t=g.frames[b][j];++seen[t];g.frame[t]=b;g.leaf[t]=8+j;for(unsigned k=0;k<8;++k)check(dot(g.roots[t],g.roots[g.frames[b][k]])==int(j==k?8:0),"each frame is an exact rational orthogonal basis and remains unit-orthogonal in F3");}for(auto x:seen)check(x==1,"every independent data port belongs to exactly one basis");
 const std::array<unsigned,9> ix={0,1,2,4,6,8,10,12,56};auto B=[&](unsigned s,unsigned t){return s==t||orth(g,s,t);};std::array<unsigned,9> inv{};for(unsigned i=0;i<9;++i){for(unsigned j=0;j<9;++j)inv[i]|=unsigned(B(ix[i],ix[j]))<<j;inv[i]|=1u<<(9+i);}for(unsigned j=0;j<9;++j){unsigned p=j;while(p<9&&!((inv[p]>>j)&1))++p;check(p<9,"rank-nine fitting principal block is invertible");std::swap(inv[p],inv[j]);for(unsigned i=0;i<9;++i)if(i!=j&&((inv[i]>>j)&1))inv[i]^=inv[j];}
 for(unsigned t=0;t<120;++t){unsigned col=0;for(unsigned j=0;j<9;++j)col|=unsigned(B(ix[j],t))<<j;g.R[t]=col;for(unsigned j=0;j<9;++j)g.G[t]|=parity((inv[j]>>9)&col)<<j;}for(unsigned s=0;s<120;++s)for(unsigned t=0;t<120;++t)check(parity(g.R[s]&g.G[t])==unsigned(B(s,t)),"all entries of the binary fitting remain correct");return g;
}
struct Rect {unsigned sf,sn,tf,tn,sm,tm;};
using Plan=std::vector<Rect>;
using Flags=std::array<unsigned,15>;
struct Trees {Flags source{},target{};};
struct Pair {std::array<unsigned char,256> uni{},inter{};};
std::array<std::array<unsigned,16>,21> menu{};
std::array<Pair,225> pairs{};
unsigned identity_flag=0;std::uint64_t score_calls=0;
unsigned nm(unsigned flag,unsigned node){return menu[flag][node];}
void prepare(const Geometry& g){unsigned count=0;for(unsigned a=1;a<8;++a)for(unsigned b=1;b<8;++b)if(b!=a&&b<(b^a)){unsigned c=1;while(c==a||c==b||c==(a^b))++c;check(count<21,"at most twenty-one affine flags");std::array<unsigned,8> perm{};for(unsigned x=0;x<8;++x){const unsigned j=4*parity(a&x)+2*parity(b&x)+parity(c&x);perm[j]=x;}for(unsigned n=1;n<=15;++n)for(unsigned j=0;j<8;++j)if(mask[n]&(1u<<j))menu[count][n]|=1u<<perm[j];if(a==4&&b==2&&c==1)identity_flag=count;++count;}check(count==21,"all twenty-one linear flags, without enumerating 8! permutations");
 for(unsigned sf=0;sf<15;++sf)for(unsigned tf=0;tf<15;++tf){auto& p=pairs[15*sf+tf];std::array<unsigned,8> row{};for(unsigned j=0;j<8;++j)for(unsigned k=0;k<8;++k)row[j]|=unsigned(orth(g,g.frames[tf][k],g.frames[sf][j]))<<k;p.inter[0]=255;for(unsigned s=1;s<256;++s){const unsigned bit=unsigned(__builtin_ctz(s)),rest=s&(s-1);p.uni[s]=static_cast<unsigned char>(p.uni[rest]|row[bit]);p.inter[s]=static_cast<unsigned char>(p.inter[rest]&row[bit]);}}
}
unsigned edges(const Geometry& g,unsigned sf,unsigned sn,unsigned tf,unsigned tn){unsigned z=0;for(unsigned j=0;j<8;++j)if(mask[sn]&(1u<<j))for(unsigned k=0;k<8;++k)if(mask[tn]&(1u<<k))z+=orth(g,g.frames[tf][k],g.frames[sf][j]);return z;}
std::uint64_t entropy(unsigned a,unsigned b){const unsigned c=8-a-b;auto h=[](unsigned r)->std::uint64_t{return r<=1?0:std::uint64_t(r)*std::uint64_t(lnratio(r,1,false));};return h(8)-h(a)-h(b)-h(c);}
using Choices=std::array<std::array<unsigned char,16>,16>;
std::uint64_t solve(unsigned sf,unsigned tf,unsigned fs,unsigned ft,bool both,Choices* output=nullptr){std::array<std::array<std::uint64_t,16>,16> dp{};Choices choice{};const auto& p=pairs[15*sf+tf];
 for(int sn=15;sn>=1;--sn)for(int tn=15;tn>=1;--tn){const auto s=unsigned(sn),t=unsigned(tn),a=pop(mask[s]),b=pop(mask[t]),sm=nm(fs,s),tm=nm(ft,t);auto best=std::numeric_limits<std::uint64_t>::max()/4;unsigned char ch=4;if(!(tm&p.uni[sm])){choice[s][t]=3;continue;}if((tm&p.inter[sm])==tm&&(both||t>=8)){check(a+b<=8,"an orthogonal rectangle has a legal residual projector");best=entropy(a,b);ch=0;}if(s<8){const auto x=dp[2*s][t]+dp[2*s+1][t];if(x<best){best=x;ch=1;}}if(t<8){const auto x=dp[s][2*t]+dp[s][2*t+1];if(x<best){best=x;ch=2;}}check(ch<4,"every nonempty grid has a legal finite split");dp[s][t]=best;choice[s][t]=ch;}
 if(output){*output=choice;}return dp[1][1];
}
Trees optimize(){Trees t;t.source.fill(identity_flag);t.target.fill(identity_flag);auto value=[&](unsigned sf,unsigned tf,unsigned fs,unsigned ft){check(++score_calls<=20000,"fixed coordinate-descent score budget");return solve(sf,tf,fs,ft,true);};
 for(unsigned pass=0;pass<2;++pass)for(unsigned axis=0;axis<2;++axis)for(unsigned f=0;f<15;++f){auto& chosen=axis?t.target[f]:t.source[f];auto best=std::numeric_limits<std::uint64_t>::max();unsigned pick=chosen;for(unsigned flag=0;flag<21;++flag){std::uint64_t cost=0;for(unsigned other=0;other<15;++other)cost+=axis?value(other,f,t.source[other],flag):value(f,other,flag,t.target[other]);if(cost<best){best=cost;pick=flag;}}chosen=pick;}
 std::cout<<"FLAGS source=";for(auto x:t.source)std::cout<<x<<",";std::cout<<" target=";for(auto x:t.target)std::cout<<x<<",";std::cout<<" score_calls="<<score_calls<<" local_search_only=1\n";return t;
}
Trees frozen(){Trees t;t.source={9,0,0,4,0,16,1,9,15,9,9,1,13,1,15};t.target={10,2,0,10,4,15,0,10,16,11,14,0,14,10,15};return t;}
Plan make_plan(const Geometry& g,bool both,const Trees& trees){Plan out;out.reserve(7560);for(unsigned sf=0;sf<15;++sf)for(unsigned tf=0;tf<15;++tf){Choices choice{};solve(sf,tf,trees.source[sf],trees.target[tf],both,&choice);
 auto emit=[&](auto&& self,unsigned s,unsigned t)->void{switch(choice[s][t]){case 0:check(out.size()<7560,"explicit side bank never exceeds the original edge count");out.push_back({sf,s,tf,t,nm(trees.source[sf],s),nm(trees.target[tf],t)});break;case 1:self(self,2*s,t);self(self,2*s+1,t);break;case 2:self(self,s,2*t);self(self,s,2*t+1);break;case 3:break;default:throw std::runtime_error("invalid rectangle choice");}};emit(emit,1,1);
 }
 std::array<std::array<std::uint64_t,2>,120> cover{};unsigned total=0;for(auto r:out)for(unsigned k=0;k<8;++k)if(r.tm&(1u<<k)){const auto s=g.frames[r.tf][k];for(unsigned j=0;j<8;++j)if(r.sm&(1u<<j)){const auto t=g.frames[r.sf][j];check(orth(g,s,t),"every rectangular entry is an actual required zero pair");const auto bit=std::uint64_t(1)<<(t%64);check(!(cover[s][t/64]&bit),"rectangles do not cancel or duplicate an adjacency entry");cover[s][t/64]|=bit;++total;}}
 for(unsigned s=0;s<120;++s){for(unsigned t=0;t<120;++t)check(bool((cover[s][t/64]>>(t%64))&1)==orth(g,s,t),"the entire dirty side factor is exactly the old adjacency");}check(total==7560,"all 7560 directed required contacts covered once");return out;
}
void invoice(const Plan& plan,bool both,unsigned variant){std::array<unsigned,37> paid{},prod{};prod[8]=5*unsigned(plan.size());prod[36]=480;paid[1]=45;paid[7]=45+1200+(both?0:600);for(unsigned r:{1u,2u,4u})paid[r]+=both?1200:600;
 std::array<std::array<unsigned,9>,9> hist{};for(auto x:plan){const auto a=pop(mask[x.sn]),b=pop(mask[x.tn]);++hist[a][b];paid[a]+=5;paid[b]+=5;if(8-a-b)paid[8-a-b]+=5;}
 unsigned pm=0,tm=0;for(unsigned r=1;r<=36;++r){pm+=r*paid[r];tm+=r*prod[r];if(paid[r])check(r<8,"every paid query stays below all productive ranks");}check(tm-pm==120,"all extra source/target flag jumps, inactive calls and split centers are paid");
 std::cout<<"PLAN both_trees="<<both<<" side_fields="<<plan.size()<<" rank_surplus="<<tm-pm<<" rectangles=";for(unsigned a=1;a<=7;++a)for(unsigned b=1;b<=7;++b)if(hist[a][b])std::cout<<a<<"x"<<b<<":"<<hist[a][b]<<",";std::cout<<"\nPAID ";for(unsigned r=1;r<=36;++r)if(paid[r])std::cout<<r<<":"<<paid[r]<<",";std::cout<<"\nPRODUCTIVE 8:"<<prod[8]<<",36:480\n";
 auto bound=[&](const auto& p,unsigned den,bool upper){U total=0;for(unsigned r=1;r<=36;++r)if(p[r]){const auto l=lnratio(36,r,upper);if(upper)total+=ceildiv(U(r)*p[r]*den*Q*Q,36*(U(den)*Q-l));else total+=U(r)*p[r]*(U(den)*Q+l)/(36*U(den));}return total;};
 for(unsigned den:{400u,500u,600u,700u,800u,900u,1000u,1100u,1200u,1350u,1400u,1500u,1600u,1650u,1700u,1800u,2000u}){const auto pu=bound(paid,den,true),pl=bound(paid,den,false),tu=bound(prod,den,true),tl=bound(prod,den,false);std::cout<<"MOMENT both="<<both<<" saving=1/"<<den<<" status="<<(pu<tl?"WIN":(pl>tu?"REJECT":"UNDECIDED"))<<" pu="<<dec(pu)<<" tl="<<dec(tl)<<" pl="<<dec(pl)<<" tu="<<dec(tu)<<"\n";if(variant==2&&den==1400)check(pu<tl,"the frozen complete native tariff contracts at sigma=1-1/1400");if(variant==2&&den==1350)check(pl>tu,"the same frozen tariff rejects saving 1/1350");}
 if(variant==2){const std::array<unsigned,7> expected={27445,10400,2200,4340,7760,8120,1245};for(unsigned i=0;i<7;++i)check(paid[i+1]==expected[i],"frozen emitted tariff equals its literal plan invoice");check(plan.size()==3782&&prod[8]==18910,"frozen side and output counts");using V=unsigned __int128;constexpr V k=1410,num=k-1,den=k*k;check(num*1420>den&&num*1430>den&&num*1450>den&&num*1400<den,"phase/movement/routing/native/full-bit slack is exact");}
}
void fixture(const Geometry& g,const Plan& plan,bool both,const Trees& trees,unsigned frequency,bool bad,bool paired,bool inverse){std::array<unsigned,8> omega{},zeta{};unsigned other=(frequency*311+821)%6561,norm=0;for(unsigned i=0;i<8;++i){omega[i]=frequency%3;frequency/=3;zeta[i]=other%3;other/=3;norm=(norm+(paired?omega[i]*zeta[i]:2*omega[i]*omega[i]))%3;}if(inverse)norm=m3(-int(norm));std::array<unsigned,120> line{},x{},y{},xf{},yf{};for(unsigned t=0;t<120;++t){int d=0,e=0;for(unsigned j=0;j<8;++j){d-=g.roots[t][j]*int(omega[j]);e-=g.roots[t][j]*int(zeta[j]);}line[t]=m3((inverse?-1:1)*(paired?2*d*e:d*d));x[t]=next()&3;y[t]=next()&3;xf[t]=line[t];}
 std::array<std::array<unsigned,16>,15> phase{},targetphase{};for(unsigned f=0;f<15;++f){for(unsigned n=1;n<=15;++n)for(unsigned j=0;j<8;++j){if(nm(trees.source[f],n)&(1u<<j))phase[f][n]=(phase[f][n]+line[g.frames[f][j]])%3;if(nm(trees.target[f],n)&(1u<<j))targetphase[f][n]=(targetphase[f][n]+line[g.frames[f][j]])%3;}check(phase[f][1]==norm&&targetphase[f][1]==norm,"every full root basis has the same full frame");}
 std::vector<unsigned char> side(plan.size()),frame(plan.size());for(auto& a:side)a=static_cast<unsigned char>(next()&3);const auto x0=x,y0=y;const auto side0=side;auto warp=[&](unsigned& value,unsigned& current,unsigned target){value=mul(ep(int(target)-int(current)),value);current=target;};auto sidewarp=[&](unsigned e,unsigned target){side[e]=static_cast<unsigned char>(mul(ep(int(target)-int(frame[e])),side[e]));frame[e]=static_cast<unsigned char>(target);};
 for(unsigned e=0;e<plan.size();++e){const auto r=plan[e];for(unsigned j=0;j<8;++j)if(r.tm&(1u<<j))y[g.frames[r.tf][j]]^=side[e];}
 for(int n=15;n>=1;--n){for(unsigned f=0;f<15;++f)for(unsigned j=0;j<8;++j)if(nm(trees.source[f],unsigned(n))&(1u<<j))warp(x[g.frames[f][j]],xf[g.frames[f][j]],phase[f][unsigned(n)]);for(unsigned e=0;e<plan.size();++e)if(plan[e].sn==unsigned(n)){const auto r=plan[e];sidewarp(e,phase[r.sf][r.sn]);for(unsigned j=0;j<8;++j)if(r.sm&(1u<<j))side[e]^=static_cast<unsigned char>(x[g.frames[r.sf][j]]);}}
 for(unsigned i=0;i<9;++i){unsigned owned=0;for(unsigned t=0;t<120;++t)if((g.G[t]>>i)&1)owned^=x[t];owned=mul(ep(-int(line[0])),owned);owned=mul(ep(int(line[0])-int(norm)),owned);for(unsigned s=0;s<120;++s)if((g.R[s]>>i)&1)y[s]^=owned;owned=0;check(owned==0,"owned increment erased after its two paid support pieces");}
 bool skipped=false;auto middle=[&](unsigned e){const auto r=plan[e];const auto target=m3(int(norm)-int(targetphase[r.tf][r.tn]));if(bad&&!skipped&&target!=frame[e]&&side[e]){frame[e]=static_cast<unsigned char>(target);skipped=true;}else sidewarp(e,target);for(unsigned j=0;j<8;++j)if(r.tm&(1u<<j))y[g.frames[r.tf][j]]^=side[e];};
 if(both){for(unsigned n=1;n<=15;++n){for(unsigned f=0;f<15;++f)for(unsigned j=0;j<8;++j)if(nm(trees.target[f],n)&(1u<<j))warp(y[g.frames[f][j]],yf[g.frames[f][j]],m3(int(norm)-int(targetphase[f][n])));for(unsigned e=0;e<plan.size();++e)if(plan[e].tn==n)middle(e);}}else{for(unsigned t=0;t<120;++t)warp(y[t],yf[t],m3(int(norm)-int(line[t])));for(unsigned e=0;e<plan.size();++e)middle(e);}
 for(unsigned e=0;e<plan.size();++e){const auto r=plan[e];sidewarp(e,norm);for(unsigned j=0;j<8;++j)if(r.sm&(1u<<j))side[e]^=static_cast<unsigned char>(x[g.frames[r.sf][j]]);}
 bool valid=true;for(unsigned t=0;t<120;++t){valid&=x[t]==mul(ep(int(norm)-int(line[t])),x0[t]);valid&=y[t]==mul(ep(int(norm)-int(line[t])),y0[t]^mul(ep(-int(line[t])),x0[t]));}for(unsigned e=0;e<plan.size();++e)valid&=side[e]==mul(ep(int(norm)),side0[e]);if(bad)check(skipped&&!valid,"omitting an actual middle-frame query fails arbitrary dirty endpoints");else check(valid,"the whole grouped raw word returns every main and arbitrary side endpoint exactly");
}
void ceiling(){U pl=0;for(auto x:std::array<std::array<unsigned,2>,2>{{{7,2400},{8,45}}})pl+=U(x[0])*x[1]*(U(200)*Q+lnratio(36,x[0],false))/(36*U(200));const U target=480*Q;check(pl>target,"even deleting all balanced helper debt cannot certify sigma<=199/200 with this core and caller");std::cout<<"SCOPED_CEILING sigma=199/200 paid_lower="<<dec(pl)<<" target_exact="<<dec(target)<<" applies_only_to_fixed_E8_core_and_caller\n";}
void run_all(){(void)&run;(void)&profile;(void)&local_fixtures;(void)&edges;(void)&optimize;const auto g=geometry();prepare(g);Trees identity;identity.source.fill(identity_flag);identity.target.fill(identity_flag);for(unsigned variant=0;variant<3;++variant){const bool both=variant!=0;const auto trees=variant==2?frozen():identity;std::cout<<"VARIANT "<<variant<<" frozen_without_discovery="<<(variant==2)<<"\n";const auto plan=make_plan(g,both,trees);invoice(plan,both,variant);for(bool paired:{false,true})for(bool inverse:{false,true}){for(unsigned j=0;j<64;++j)fixture(g,plan,both,trees,(j*97+1)%6561,false,paired,inverse);fixture(g,plan,both,trees,1,true,paired,inverse);}std::cout<<"RAW both_trees="<<both<<" arbitrary_fixtures=256 quadratic_and_paired=1 both_frame_signs=1 deleted_middle_query_controls=REJECTED\n";}ceiling();}
}
#ifndef E8_ORTHOGONAL_TREE_SIDES_LIBRARY_ONLY
int main(){if(!guard()){std::cerr<<"REFUSED: SELF-only guard unavailable\n";return 2;}try{tree_sides::run_all();PROCESS_MEMORY_COUNTERS pm{};pm.cb=sizeof(pm);GetProcessMemoryInfo(GetCurrentProcess(),&pm,sizeof(pm));std::cout<<"PASS checks="<<checks<<" peak_bytes="<<pm.PeakWorkingSetSize<<"\nlimits=64MiB/10CPUSeconds;roots=120;bases=15;tree_nodes=15;side_fields<=7560;DP_states_per_score<=225;score_calls<=20000;single thread\n";}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
#endif
